<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/user.php';
$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $username=trim($_POST['username']??''); $user=find_user_by_username($username); $ok=$user && $user['status']==='active' && (!$user['locked_until'] || strtotime($user['locked_until'])<time()) && password_verify($_POST['password']??'',$user['password_hash']); db()->prepare('INSERT INTO login_history(user_id,username,ip_address,user_agent,browser,success) VALUES (?,?,?,?,?,?)')->execute([$user['id']??null,$username,$_SERVER['REMOTE_ADDR']??'',substr($_SERVER['HTTP_USER_AGENT']??'',0,255),substr($_SERVER['HTTP_USER_AGENT']??'',0,120),$ok?1:0]); if($ok){session_regenerate_id(true); db()->prepare('UPDATE users SET login_attempts=0,last_login=NOW(),locked_until=NULL WHERE id=?')->execute([$user['id']]); $_SESSION['user']=['id'=>(int)$user['id'],'username'=>$user['username'],'email'=>$user['email'],'role_id'=>(int)$user['role_id'],'permissions'=>load_permissions((int)$user['role_id'])]; audit('login','users',(int)$user['id']); redirect('/auth/profile.php');} if($user){$attempts=(int)$user['login_attempts']+1; db()->prepare('UPDATE users SET login_attempts=?, locked_until=IF(? >= 5, DATE_ADD(NOW(), INTERVAL 15 MINUTE), locked_until) WHERE id=?')->execute([$attempts,$attempts,$user['id']]);} $error='Invalid username or password, or account is not active.'; }
auth_header('Login'); ?><h2 class="brand">Welcome back</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-floating"><input name="username" class="form-control" placeholder="Username" required><label>Username</label></div><div class="input-group"><div class="form-floating"><input type="password" id="password" name="password" class="form-control" placeholder="Password" required><label>Password</label></div><button class="btn btn-outline-secondary" type="button" onclick="togglePassword('password')"><i class="bi bi-eye"></i></button></div><label><input type="checkbox" name="remember"> Remember me / keep me signed in</label><button class="btn btn-premium">Login</button></form><div class="mt-3 d-flex justify-content-between"><a href="register.php">Register</a><a href="forgot-password.php">Forgot password?</a></div><?php auth_footer(); ?>
